def word_count(text: str) -> dict:
    """Count lowercase words (split on whitespace, strip .,!? from both ends)."""
    words = text.split()
    cleaned_words = []
    for word in words:
        stripped = word.strip('.,!?")
        if stripped:
            cleaned_words.append(stripped.lower())
    return dict(
        (word, cleaned_words.count(word)) for word in set(cleaned_words)
    )

