def camel_to_snake(s: str) -> str:
    result = []
    prev_char_upper = False
    for char in s:
        if char.isupper():
            if prev_char_upper:
                result.append(char.lower())
            else:
                result.append('_')
                result.append(char.lower())
            prev_char_upper = True
        else:
            result.append(char)
            prev_char_upper = False
    return ''.join(result)

